//! Google Drive API v3 implementation.//!//! All API calls go through the host's HTTP capability, which handles//! credential injection and rate limiting. The WASM tool never sees//! the actual OAuth token.use crate::near::agent::host;use crate::types::*;const DRIVE_API_BASE: &str = "https://www.googleapis.com/drive/v3";const UPLOAD_API_BASE: &str = "https://www.googleapis.com/upload/drive/v3";/// Standard fields to request for file metadata.const FILE_FIELDS: &str = "id,name,mimeType,description,size,createdTime,modifiedTime,\    webViewLink,parents,shared,starred,trashed,ownedByMe,driveId,\    owners(emailAddress,displayName)";/// Make a Drive API call.fn api_call(method: &str, path: &str, body: Option<&str>) -> Result<String, String> {    let url = format!("{}/{}", DRIVE_API_BASE, path);    let headers = if body.is_some() {        r#"{"Content-Type": "application/json"}"#    } else {        "{}"    };    let body_bytes = body.map(|b| b.as_bytes().to_vec());    host::log(        host::LogLevel::Debug,        &format!("Drive API: {} {}", method, path),    );    let response = host::http_request(method, &url, headers, body_bytes.as_deref(), None)?;    if response.status < 200 || response.status >= 300 {        let body_text = String::from_utf8_lossy(&response.body);        return Err(format!(            "Drive API returned status {}: {}",            response.status, body_text        ));    }    if response.body.is_empty() {        return Ok(String::new());    }    String::from_utf8(response.body).map_err(|e| format!("Invalid UTF-8 in response: {}", e))}/// Make a raw API call that returns bytes (for file downloads).fn api_call_raw(method: &str, url: &str) -> Result<Vec<u8>, String> {    host::log(        host::LogLevel::Debug,        &format!("Drive API raw: {} {}", method, url),    );    let response = host::http_request(method, url, "{}", None, None)?;    if response.status < 200 || response.status >= 300 {        let body_text = String::from_utf8_lossy(&response.body);        return Err(format!(            "Drive API returned status {}: {}",            response.status, body_text        ));    }    Ok(response.body)}/// Parse a file resource from the API response.fn parse_file(v: &serde_json::Value) -> DriveFile {    let mime_type = v["mimeType"].as_str().unwrap_or("").to_string();    DriveFile {        id: v["id"].as_str().unwrap_or("").to_string(),        name: v["name"].as_str().unwrap_or("").to_string(),        is_folder: mime_type == "application/vnd.google-apps.folder",        mime_type,        description: v["description"].as_str().map(|s| s.to_string()),        size: v["size"].as_str().map(|s| s.to_string()),        created_time: v["createdTime"].as_str().map(|s| s.to_string()),        modified_time: v["modifiedTime"].as_str().map(|s| s.to_string()),        web_view_link: v["webViewLink"].as_str().map(|s| s.to_string()),        parents: v["parents"]            .as_array()            .map(|arr| {                arr.iter()                    .filter_map(|p| p.as_str().map(|s| s.to_string()))                    .collect()            })            .unwrap_or_default(),        shared: v["shared"].as_bool().unwrap_or(false),        starred: v["starred"].as_bool().unwrap_or(false),        trashed: v["trashed"].as_bool().unwrap_or(false),        owned_by_me: v["ownedByMe"].as_bool().unwrap_or(false),        drive_id: v["driveId"].as_str().map(|s| s.to_string()),        owners: v["owners"]            .as_array()            .map(|arr| {                arr.iter()                    .map(|o| Owner {                        email: o["emailAddress"].as_str().unwrap_or("").to_string(),                        display_name: o["displayName"].as_str().map(|s| s.to_string()),                    })                    .collect()            })            .unwrap_or_default(),    }}/// List/search files.